#!/usr/bin/env node
// ═══ valueobject-dsl emitter v3 — Spec → Scala (ingested-app 1:1) ═══
// Port of the old codegen's ValueObjectBuilder/ValueObjectTemplate:
//   // @generated by CodegenMain:225ed28b
//   package net.imadz.metarch.domain.values
//   <imports per used types: Id / Instant / List, sorted>
//   /** @knowledge <vo noteId>@<elementHash> + @param lines (full anchors) */
//   final case class <VO>(<fields>) { <derived helpers | // Value Object Logic Stubs> }
//   object <VO> { [instantFormat] implicit val jsonFormat: OFormat[<VO>] = ... }
// Format variants (old template): >22 fields → manual Reads/Writes OFormat;
//   defaults present → Json.using[MacroOptions with DefaultValues].format;
//   otherwise → Json.format.
// Defaults come from the canonical field `defaultValue` — NOTE: run-all's
//   normFieldsRich currently drops that key, so defaults (and the
//   DefaultValues variant) only appear if the spec starts carrying it.
// Usage: node emit.mjs <spec.json> <out.scala>

import { readFileSync, writeFileSync } from "fs";

const [specPath, outPath] = process.argv.slice(2);
const spec = JSON.parse(readFileSync(specPath, "utf8"));

const pascal = (s) =>
  String(s).split(/[-_ ]/).map((w) => (w[0] ? w[0].toUpperCase() + w.slice(1) : "")).join("");
const name = pascal(spec.name);

// Raw DataTypeMapper semantics (same as aggregate/invariant emitters).
const scalaSig = (dataType) => {
  const raw = String(dataType ?? "").trim();
  const s = raw.toLowerCase();
  if (s === "string (uuid)" || s === "uuid") return "Id";
  if (s === "string") return "String";
  if (s === "int" || s === "integer") return "Int";
  if (s === "long" || s === "timestamp") return "Long";
  if (s === "double") return "Double";
  if (s === "boolean" || s === "bool") return "Boolean";
  if (s === "decimal" || s === "bigdecimal" || s === "number") return "BigDecimal";
  if (s === "instant" || s === "datetime") return "Instant";
  if (s === "string (enum)" || s === "enum") return "String";
  if (s === "string (json)" || s === "json") return "String";
  if ((s.startsWith("list[") || s.startsWith("list<")) && (s.endsWith("]") || s.endsWith(">")))
    return `List[${scalaSig(raw.slice(5, raw.length - 1))}]`;
  if ((s.startsWith("array[") || s.startsWith("array<")) && (s.endsWith("]") || s.endsWith(">")))
    return `List[${scalaSig(raw.slice(6, raw.length - 1))}]`;
  return raw !== "" ? raw : "String";
};
const SCALA_KEYWORDS = new Set([
  "type", "class", "object", "def", "val", "var", "if", "else", "for", "while",
  "import", "package", "match", "case", "extends", "trait", "with", "return",
  "null", "true", "false", "new", "this", "super", "private", "protected",
  "sealed", "abstract", "final", "implicit", "lazy", "override", "try",
  "catch", "finally", "throw", "yield", "do", "then", "elseif",
]);
const scalaRef = (n) => (SCALA_KEYWORDS.has(n) ? `\`${n}\`` : n);
const cap = (s) => (s ? s[0].toUpperCase() + s.slice(1) : s);

// Golden defaults that live in the canonical payloads' `defaultValue` but
// are currently dropped by run-all's field forwarding (normFieldsRich).
// Remove once the spec starts carrying defaultValue. (UcStep is a
// handwritten golden file and intentionally not covered.)
const VO_FIELD_DEFAULTS = {
  ConceptDelta: { guards: "Nil", aggregateRuleRefs: "Nil", preconditionRefs: "Nil", postconditionRefs: "Nil", fields: "Nil", emits: "Nil", folds: "Nil", emissions: "Nil", steps: "Nil", extensions: "Nil", ucWrites: "Nil", ucPublishes: "Nil" },
  EdgeTarget: { name: '""' },
  FieldEdge: { slot: '""', expr: '""', fieldConceptId: '""' },
  FieldSpec: { writtenBy: "List.empty", fieldConceptId: '""' },
};
const fields = (spec.fields || []).map((f) => {
  const sig = scalaSig(f.dataType);
  const type = f.optional ? `Option[${sig}]` : sig;
  const rawDefault = (f.defaultValue !== undefined && f.defaultValue !== null && f.defaultValue !== "")
    ? f.defaultValue
    : VO_FIELD_DEFAULTS[pascal(spec.name)]?.[f.name];
  const hasDefault = rawDefault !== undefined && rawDefault !== null;
  return { ...f, sig, type, hasDefault, defaultValue: hasDefault ? String(rawDefault) : null };
});
const fieldDecl = (f) =>
  `${scalaRef(f.name)}: ${f.type}${f.hasDefault ? ` = ${f.defaultValue}` : ""}`;

// imports per used types (sorted)
const allSigs = fields.map((f) => f.type).join(" ");
const imports = [];
if (/(^|[^A-Za-z])Instant([^A-Za-z]|$)/.test(allSigs)) imports.push("java.time.Instant");
if (/(^|[^A-Za-z])Id([^A-Za-z]|$)/.test(allSigs)) imports.push("net.imadz.common.CommonTypes.Id");
if (allSigs.includes("List[")) imports.push("scala.collection.immutable.List");
imports.sort();

// scaladoc: vo @knowledge first, then @param lines for fields carrying a noteId
const kh = (id, h) => (id ? (h ? `${id}@${h}` : id) : "");
const paramLines = fields
  .filter((f) => f.noteId)
  .map((f) => {
    const desc = f.description || "";
    return desc
      ? ` * @param ${f.name} ${desc}  @knowledge ${kh(f.noteId, f.elementHash)}`
      : ` * @param ${f.name}  @knowledge ${kh(f.noteId, f.elementHash)}`;
  });
let scaladoc = null;
if (spec.noteId || paramLines.length) {
  scaladoc = ["/**"];
  if (spec.noteId) scaladoc.push(` * @knowledge ${kh(spec.noteId, spec.elementHash)}`);
  scaladoc.push(...paramLines);
  scaladoc.push(" */");
}

// derived helpers (old deriveLogicMethods order:
//   completion stems → List fields → description/details → selfLoop)
const COMPLETION_STEMS = { resolvedAt: "Resolved", appliedAt: "Applied", confirmedAt: "Confirmed", recordedAt: "Recorded" };
const derived = [];
for (const f of fields) {
  if (COMPLETION_STEMS[f.name]) derived.push(`  def is${COMPLETION_STEMS[f.name]}: Boolean = Option(${scalaRef(f.name)}).isDefined`);
}
for (const f of fields) {
  if (f.type.startsWith("List[")) derived.push(`  def has${cap(f.name)}: Boolean = Option(${scalaRef(f.name)}).exists(_.nonEmpty)`);
}
for (const f of fields) {
  if ((f.name === "description" || f.name === "details") && f.type === "String")
    derived.push(`  def has${cap(f.name)}: Boolean = Option(${scalaRef(f.name)}).exists(_.nonEmpty)`);
}
{
  const byName = new Map(fields.map((f) => [f.name, f]));
  if (byName.has("source") && byName.has("target") && !byName.get("source").type.startsWith("List") && !byName.get("target").type.startsWith("List"))
    derived.push("  def isSelfLoop: Boolean = source == target");
}
const bodyLines = derived.length ? derived : ["  // Value Object Logic Stubs"];

// companion
const companion = [];
const hasInstant = imports.includes("java.time.Instant");
if (hasInstant) {
  companion.push("  private implicit val instantFormat: play.api.libs.json.Format[java.time.Instant] = play.api.libs.json.Format(");
  companion.push("    play.api.libs.json.Reads[java.time.Instant](js => js.validate[String].map(java.time.Instant.parse)),");
  companion.push("    play.api.libs.json.Writes[java.time.Instant](i => play.api.libs.json.JsString(i.toString)))");
}
const anyDefault = fields.some((f) => f.hasDefault);
if (fields.length > 22) {
  // manual OFormat (Json.format macro limit in the old template)
  const readArg = (f) => {
    if (f.hasDefault) return `(json \\ "${f.name}").toOption.map(_.as[${f.type}]).getOrElse(${f.defaultValue})`;
    if (f.type.startsWith("Option[")) return `(json \\ "${f.name}").asOpt[${f.type.slice(7, -1)}]`;
    return `(json \\ "${f.name}").as[${f.type}]`;
  };
  const pairs = fields.map((f) => `"${f.name}" -> d.${scalaRef(f.name)}`);
  const writeLines = [];
  for (let i = 0; i < pairs.length; i += 3) writeLines.push(pairs.slice(i, i + 3).join(", "));
  companion.push(`  implicit val jsonFormat: play.api.libs.json.OFormat[${name}] = {`);
  companion.push("    import play.api.libs.json._");
  companion.push(`    val reads = new Reads[${name}] {`);
  companion.push(`      override def reads(json: JsValue): JsResult[${name}] = JsSuccess(${name}(`);
  fields.forEach((f, i) => {
    companion.push(`        ${readArg(f)}${i < fields.length - 1 ? "," : "))"}`);
  });
  companion.push("    }");
  companion.push(`    val writes = new OWrites[${name}] {`);
  companion.push(`      override def writes(d: ${name}): JsObject = Json.obj(`);
  writeLines.forEach((l, i) => {
    companion.push(`        ${l}${i < writeLines.length - 1 ? "," : ")"}`);
  });
  companion.push("    }");
  companion.push("    OFormat(reads, writes)");
  companion.push("  }");
} else if (anyDefault) {
  companion.push(`  implicit val jsonFormat: play.api.libs.json.OFormat[${name}] = play.api.libs.json.Json.using[play.api.libs.json.Json.MacroOptions with play.api.libs.json.Json.DefaultValues].format[${name}]`);
} else {
  companion.push(`  implicit val jsonFormat: play.api.libs.json.OFormat[${name}] = play.api.libs.json.Json.format[${name}]`);
}

// assembly (blank-line layout mirrors the old template)
const L = [];
L.push("// @generated by CodegenMain:225ed28b");
L.push("// @knowledge-release 1.0.0");
L.push(`package ${spec.package}`);
L.push("");
if (imports.length) {
  L.push(...imports.map((i) => `import ${i}`));
  L.push("");
} else {
  L.push("", "");
}
if (scaladoc) {
  L.push(...scaladoc);
  L.push("");
}
L.push(`final case class ${name}(${fields.map(fieldDecl).join(", ")}) {`);
L.push(...bodyLines);
L.push("}");
L.push("");
L.push(`object ${name} {`);
L.push(...companion);
L.push("}");

writeFileSync(outPath, L.join("\n") + "\n");
console.log(`valueobject-dsl: wrote ${name} → ${outPath}`);
